CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE IF NOT EXISTS customers(id text PRIMARY KEY, name text NOT NULL CHECK(length(name)>0));
CREATE TABLE IF NOT EXISTS properties(id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id), name text NOT NULL, address text NOT NULL, lawn_sqft numeric NOT NULL CHECK(lawn_sqft>=0));
CREATE TABLE IF NOT EXISTS contracts(id text PRIMARY KEY, property_id text NOT NULL REFERENCES properties(id), service text NOT NULL, frequency text NOT NULL, monthly_cents integer NOT NULL CHECK(monthly_cents>=0), visits_per_month integer NOT NULL CHECK(visits_per_month>0), estimated_minutes integer NOT NULL CHECK(estimated_minutes>0));
CREATE TABLE IF NOT EXISTS crews(id text PRIMARY KEY, name text NOT NULL, workers integer NOT NULL CHECK(workers>0), hourly_cents integer NOT NULL CHECK(hourly_cents>=0));
CREATE TABLE IF NOT EXISTS visits(id text PRIMARY KEY, contract_id text NOT NULL REFERENCES contracts(id), crew_id text NOT NULL REFERENCES crews(id), scheduled_at timestamptz NOT NULL, route_order integer NOT NULL CHECK(route_order>0), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','started','completed')), started_at timestamptz, completed_at timestamptz, actual_minutes integer CHECK(actual_minutes>0), materials_cents integer NOT NULL DEFAULT 0 CHECK(materials_cents>=0), equipment_cents integer NOT NULL DEFAULT 0 CHECK(equipment_cents>=0), travel_cents integer NOT NULL DEFAULT 0 CHECK(travel_cents>=0), overhead_cents integer NOT NULL DEFAULT 0 CHECK(overhead_cents>=0), revenue_cents integer, labor_cents integer, notes text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS activity(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, visit_id text NOT NULL REFERENCES visits(id), event text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
